// Code generated by `cargo run -p codegen` — DO NOT EDIT
// Quantity: Level

#![allow(
    clippy::excessive_precision,
    clippy::unreadable_literal,
    clippy::double_parens,
    unused_parens
)]

use super::{assert_close, check_fixed, check_fixed_rescale, F32_TOL, F64_TOL, ROUND_TRIP_TOL};
use unitsnet_rs::*;

#[test]
fn decibels() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(Level::from_decibels(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = x;
        assert_close(Level::from_base(base).as_decibels(), back, F64_TOL);
        assert_close(Level::from_decibels(v).as_decibels(), v, ROUND_TRIP_TOL);
        // f32 storage.
        assert_close(
            Level::from_decibels(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            Level::from_base(base as f32).as_decibels() as f64,
            back,
            F32_TOL,
        );
    }
}

#[test]
fn nepers() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = (1.0 / 0.115129254) * x;
        assert_close(Level::from_nepers(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = 0.115129254 * x;
        assert_close(Level::from_base(base).as_nepers(), back, F64_TOL);
        assert_close(Level::from_nepers(v).as_nepers(), v, ROUND_TRIP_TOL);
        // f32 storage.
        assert_close(Level::from_nepers(v as f32).as_base() as f64, base, F32_TOL);
        assert_close(
            Level::from_base(base as f32).as_nepers() as f64,
            back,
            F32_TOL,
        );
    }
}

#[test]
fn fixed_units() {
    check_fixed::<unit::level::Decibel>();
    check_fixed_rescale::<unit::level::Decibel>();
    check_fixed::<unit::level::Neper>();
    check_fixed_rescale::<unit::level::Neper>();
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(Level::new(v, LevelUnit::Decibel), Level::from_decibels(v));
    assert_eq!(
        Level::from_base(v).convert_to(LevelUnit::Decibel),
        Level::from_base(v).as_decibels()
    );
    assert_eq!(Level::new(v, LevelUnit::Neper), Level::from_nepers(v));
    assert_eq!(
        Level::from_base(v).convert_to(LevelUnit::Neper),
        Level::from_base(v).as_nepers()
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!("dB".parse::<LevelUnit>(), Ok(LevelUnit::Decibel));
    assert_eq!(
        format!("2.5 {}", "dB").parse::<Level>(),
        Ok(Level::new(2.5, LevelUnit::Decibel))
    );
    assert_eq!("Np".parse::<LevelUnit>(), Ok(LevelUnit::Neper));
    assert_eq!(
        format!("2.5 {}", "Np").parse::<Level>(),
        Ok(Level::new(2.5, LevelUnit::Neper))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Level>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = Level::from_base(6.0);
    let b = Level::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = Level::<i64>::from_base(7);
    let b = Level::<i64>::from_base(2);
    assert_eq!(a + b, Level::from_base(9));
    assert_eq!(a % b, Level::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!([a, b].iter().sum::<Level<i64>>(), Level::from_base(9));
}
